#[derive(Clone)]
struct Items<'a>{remaining:&'a str}
impl<'a> Items<'a>{
 fn new(value:&'a str)->Result<Self,ValueError>{let value=value.trim();Ok(Self{remaining:value.strip_prefix('[').and_then(|s|s.strip_suffix(']')).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native list requires brackets"))?})}
 fn next(&mut self,control:&mut NativeDecodeControl<'_>)->Result<Option<&'a str>,ValueError>{
 if self.remaining.is_empty(){return Ok(None)}let mut depth=0usize;let mut end=self.remaining.len();
 for(index,byte)in self.remaining.bytes().enumerate(){if index%256==0{control.checkpoint()?;}match byte{b'['=>{depth+=1;if depth>2{return Err(ValueError::new(ValueRefusalKind::DepthLimit,"image native list depth exceeds field shape"));}},b']'=>{depth=depth.checked_sub(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native unmatched bracket"))?;},b',' if depth==0=>{end=index;break;},_=>{}}}
 if depth!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native unmatched bracket"));}let value=self.remaining[..end].trim();self.remaining=if end<self.remaining.len(){&self.remaining[end+1..]}else{""};if value.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native empty list element"));}Ok(Some(value))
 }
 fn count(&self,control:&mut NativeDecodeControl<'_>,maximum:usize)->Result<usize,ValueError>{let mut items=self.clone();let mut count=0usize;while items.next(control)?.is_some(){count=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native list count overflow"))?;if count>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"image native entities exceed caller row limit"));}}Ok(count)}
}
fn pair<'a>(value:&'a str,control:&mut NativeDecodeControl<'_>)->Result<(&'a str,&'a str),ValueError>{let inner=value.trim().strip_prefix('[').and_then(|s|s.strip_suffix(']')).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native pair requires brackets"))?;let mut delimiter=None;for(index,byte)in inner.bytes().enumerate(){if index%256==0{control.checkpoint()?;}match byte{b','=>{if delimiter.replace(index).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native pair has extra fields"));}},b'['|b']'=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native pair contains nested fields")),_=>{}}}let index=delimiter.ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native pair is missing a field"))?;Ok((inner[..index].trim(),inner[index+1..].trim()))}
fn hex(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,ValueError>{
 if !value.len().is_multiple_of(2){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native odd hex length"));}
