/// 🚫️ Reports an authored BRep relationship refusal.
fn brep_invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
/// 🗃️ Binds exact logical and IEEE columns to shared paid source positions.
fn details<'a>(db:&'a SqliteDatabase,name:&str,columns:usize,c:&mut SqliteSnapshotControl<'_>)->Result<RowIndex<'a>,ValueError>{RowIndex::new(db,name,columns,float_columns(name),c,"invalid BRep row identity or columns")}
/// 👪️ Validates parameter foreign identities before paying owner-ordinal ordering.
fn groups(rows:&RowIndex<'_>,parents:&RowIndex<'_>,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<usize>,ValueError>{
 for &index in rows.indices(){if parents.get(rows.row(index)?.integer(1)?,c)?.is_none(){return Err(brep_invalid("dangling BRep sequence owner"))}}rows.grouped_by(2,c,"BRep sequence ordinals must be contiguous",|row|Ok((0,Some(row.integer(1)?))))
}
/// 🛂️ Rejects contradictory analytic fields outside the actual selected variant.
fn shape(row:SqliteRow<'_>,active:&[usize])->Result<(),ValueError>{for index in 2..row.values.len(){if !active.contains(&index)&&!row.is_null(index)?{return Err(brep_invalid("contradictory BRep analytic geometry fields"))}}Ok(())}
/// 🧮️ Fills an already guarded typed parameter vector from a paid scalar owner range.
fn brep_sequence<T>(target:&mut Vec<T>,rows:&mut RowIndex<'_>,order:&[usize],id:i64,c:&mut SqliteSnapshotControl<'_>,decode:impl Fn(SqliteRow<'_>)->Result<T,ValueError>)->Result<(),ValueError>{
